import type {BlogCategory, BlogEntry} from './blogs.ts';

type BatchTuple = [
  name: string,
  url: string,
  category: BlogCategory,
  tagline: string,
  topics: string[],
  feedUrl?: string
];

const PALETTE = [
  '#1E3A8A',
  '#1D4ED8',
  '#0F766E',
  '#B45309',
  '#991B1B',
  '#1E293B',
  '#4338CA',
  '#047857',
  '#374151',
  '#7C2D12',
];

function makeId(name: string, url: string, idx: number): string {
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 28);
  let hostPart = '';
  try {
    hostPart = new URL(url).hostname.replace(/^www\./, '').split('.')[0] || '';
  } catch {
    hostPart = '';
  }
  return `${slug || hostPart || 'site'}-${idx + 181}`;
}

function buildBatchEntry(tuple: BatchTuple, idx: number): BlogEntry {
  const [name, url, category, tagline, topics, feedUrl] = tuple;
  let domain = url;
  try {
    domain = new URL(url).hostname.replace(/^www\./, '');
  } catch {
    domain = url.replace(/^https?:\/\//, '').split('/')[0] || name.toLowerCase();
  }

  const words = name.replace(/[^a-zA-Z0-9\s]/g, ' ').trim().split(/\s+/);
  const monogram =
    words.length >= 2
      ? `${words[0][0] || ''}${words[1][0] || ''}`.toUpperCase()
      : name.slice(0, 2).toUpperCase();

  return {
    id: makeId(name, url, idx),
    name,
    url,
    domain,
    feedUrl,
    category,
    author: name,
    established: 'Web',
    tagline,
    description: `${tagline} Read and browse ${name} (${domain}) directly inside PressIndex.`,
    topics: Array.from(new Set([...topics, name.toLowerCase(), domain])),
    accentHex: PALETTE[idx % PALETTE.length],
    monogram,
  };
}

